SELECT
    m.*,
    COUNT(p.participant_id) AS current_people
FROM personal_match m
LEFT JOIN personal_match_participant p
    ON m.personal_match_id = p.personal_match_id
WHERE m.latitude BETWEEN #{minLat} AND #{maxLat}
  AND m.longitude BETWEEN #{minLng} AND #{maxLng}
GROUP BY m.personal_match_id
ORDER BY m.created_at DESC;

SELECT m.*, p.status AS participantStatus FROM personal_match_participant p JOIN personal_match m ON m.personal_match_id = p.personal_match_id WHERE p.user_id = #{userId} AND p.status IN ('결제완료')
AND m.match_date >= STR_TO_DATE(CONCAT(#{month}, '-01'), '%Y-%m-%d') AND m.match_date < DATE_ADD(STR_TO_DATE(CONCAT(#{month}, '-01'), '%Y-%m-%d'), INTERVAL 1 MONTH)
AND m.sport = #{sport}
AND m.status = #{status}
ORDER BY m.match_date, m.personal_match_id LIMIT #{size} OFFSET #{offset}

SELECT COUNT(*) FROM personal_match_participant p JOIN personal_match m ON m.personal_match_id = p.personal_match_id WHERE p.user_id = #{userId} AND p.status IN ('결제완료')
AND m.match_date >= STR_TO_DATE(CONCAT(#{month}, '-01'), '%Y-%m-%d') AND m.match_date < DATE_ADD(STR_TO_DATE(CONCAT(#{month}, '-01'), '%Y-%m-%d'), INTERVAL 1 MONTH)
AND m.sport = #{sport}
AND m.status = #{status}

SELECT m.*, p.status AS participantStatus FROM personal_match_participant p JOIN personal_match m ON m.personal_match_id = p.personal_match_id WHERE p.user_id = #{userId} and p.status = '결제완료'
AND m.match_date >= STR_TO_DATE(CONCAT(#{month}, '-01'), '%Y-%m-%d') AND m.match_date < DATE_ADD(STR_TO_DATE(CONCAT(#{month}, '-01'), '%Y-%m-%d'), INTERVAL 1 MONTH)
AND m.sport = #{sport}
AND m.status = #{status}
ORDER BY m.sport, m.match_date LIMIT #{size} OFFSET #{offset}

select m.* from personal_match m where m.user_id=#{userId} and m.deleted = '0'
AND m.match_date >= STR_TO_DATE(CONCAT(#{month}, '-01'), '%Y-%m-%d') AND m.match_date < DATE_ADD(STR_TO_DATE(CONCAT(#{month}, '-01'), '%Y-%m-%d'), INTERVAL 1 MONTH)
AND m.sport = #{sport}
AND m.status = #{status}
ORDER BY m.match_date DESC

SELECT COUNT(*) FROM personal_match m WHERE m.user_id = #{userId} AND m.deleted = 0
AND m.match_date >= STR_TO_DATE(CONCAT(#{month}, '-01'), '%Y-%m-%d') AND m.match_date < DATE_ADD(STR_TO_DATE(CONCAT(#{month}, '-01'), '%Y-%m-%d'), INTERVAL 1 MONTH)
AND m.sport = #{sport}
AND m.status = #{status}

SELECT m.*
FROM personal_match m
WHERE m.user_id = #{userId}
AND m.deleted = 0

	AND m.match_date >= STR_TO_DATE(CONCAT(#{month}, '-01'), '%Y-%m-%d')
	AND m.match_date < DATE_ADD(STR_TO_DATE(CONCAT(#{month}, '-01'),
	'%Y-%m-%d'), INTERVAL 1 MONTH)


	AND m.sport = #{sport}


	AND m.status = #{status}

ORDER BY m.match_date DESC, m.personal_match_id DESC
LIMIT #{size} OFFSET #{offset}

select m.*, p.status as participantStatus from personal_match_participant p join personal_match m on m.personal_match_id = p.personal_match_id where p.user_id = #{userId} and p.status in ('PAID', 'HOST')
and m.match_date >= STR_TO_DATE(CONCAT(#{month}, '-01'), '%Y-%m-%d') and m.match_date < DATE_ADD(STR_TO_DATE(CONCAT(#{month}, '-01'), '%Y-%m-%d'), INTERVAL 1 MONTH)
order by m.match_date desc limit #{offset}, #{size}
